WITH "dab_page_cte" AS ( SELECT /*+ MATERIALIZE */ "TABLE0"."ID" AS "ID", "TABLE0"."ID" AS "c0" FROM "DBO"."PARENTS" "TABLE0" WHERE 1 = 1 ORDER BY "TABLE0"."ID" ASC OFFSET 0 ROWS FETCH NEXT 100 ROWS ONLY ), "table1_subq_cte" AS ( SELECT "k0", COALESCE(JSON_ARRAYAGG(json_doc FORMAT JSON ORDER BY "rn" RETURNING CLOB), TO_CLOB(JSON_ARRAY())) AS "data" FROM ( SELECT JSON_OBJECT('id' VALUE "TABLE1"."id" NULL ON NULL RETURNING VARCHAR2(4000)) AS json_doc, "TABLE1"."k0" AS "k0", "TABLE1"."rn" AS "rn" FROM ( SELECT "TABLE1"."id" AS "id", "TABLE1"."parent_id" AS "k0", ROW_NUMBER() OVER (PARTITION BY "TABLE1"."parent_id" ORDER BY "TABLE1"."id" ASC) AS "rn" FROM "DBO"."CHILDREN" "TABLE1" INNER JOIN (SELECT DISTINCT "c0" FROM "dab_page_cte") "dab_page" ON ("dab_page"."c0" = "TABLE1"."parent_id") WHERE 1 = 1 ) "TABLE1" WHERE "TABLE1"."rn" <= 100 ) ranked_rows GROUP BY "k0" ) SELECT COALESCE(JSON_ARRAYAGG("json_doc" FORMAT JSON ORDER BY "__dab_ord" RETURNING CLOB), TO_CLOB(JSON_ARRAY())) AS "data" FROM ( SELECT JSON_OBJECT('id' VALUE "id", 'children' VALUE "children" FORMAT JSON NULL ON NULL RETURNING CLOB) AS "json_doc", ROWNUM AS "__dab_ord" FROM ( SELECT "TABLE0"."ID" AS "id", COALESCE("table1_subq_cte"."data", TO_CLOB(JSON_ARRAY())) AS "children" FROM "dab_page_cte" "TABLE0" LEFT OUTER JOIN "table1_subq_cte" ON "table1_subq_cte"."k0" = "TABLE0"."ID" WHERE 1 = 1 ORDER BY "TABLE0"."ID" ASC OFFSET 0 ROWS FETCH NEXT 100 ROWS ONLY ) ) "subq0"